"kind": "propose",
"summary": "Increase memory limit for app container in reports Deployment to address OOMKilled incidents",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_too_low",
    "summary": "Current revision's memory limit (1Gi) is insufficient for workload",
    "supporting": ["oom_killed_current_revision", "ev-rollout_history"],
