"proposal": {
  "capability": "deployment.set-resources",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "shop", "name": "reports", "uid": "uid-deployment-reports"},
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "1250Mi"
        }
      }
    }
  },
  "expected_effect": "Raise memory limit to 1250Mi to prevent OOMKilled incidents",
  "rationale": "Current revision (4) has 1Gi memory limit but is OOMKilled. Increasing by 25% to 1250Mi addresses potential memory insufficiency without requiring usage metrics. Earlier revision (3) had same limit but no reported issues, suggesting workload change may require higher limit. Node memory pressure is false, ruling out node-level issues. No evidence of memory leaks or long-running OOM issues. Fix aligns with guidelines for memory_limit_too_low when OOMKilled occurs without rollout-related factors. No GitOps markers prevent automated rollback, so adjustment is justified as temporary mitigation. No ",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events"],
  "cited_predicates": ["oom_killed_current_revision", "evicted_for_node_memory", "oom_after_long_run"]
}
}
